CREATE DATABASE IF NOT EXISTS auspify_sms CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE auspify_sms;
CREATE TABLE IF NOT EXISTS admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_login DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS students(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_code VARCHAR(40) NOT NULL UNIQUE,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30) NULL,gender ENUM('Female','Male','Other','Prefer not to say') NULL,date_of_birth DATE NULL,class_name VARCHAR(80) NOT NULL,section_name VARCHAR(40) NULL,admission_date DATE NULL,guardian_name VARCHAR(120) NULL,guardian_phone VARCHAR(30) NULL,address VARCHAR(500) NULL,status ENUM('Active','Inactive','Graduated','Transferred') NOT NULL DEFAULT 'Active',notes TEXT NULL,photo_path VARCHAR(255) NULL,qualifications TEXT NULL,achievements TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_student_name(last_name,first_name),KEY idx_student_class(class_name),KEY idx_student_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id BIGINT UNSIGNED NULL,details VARCHAR(500) NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_activity_created(created_at),CONSTRAINT fk_activity_admin FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB;
